<?php if(!$vinculos): ?><div class="cruce-empty">Todavía no se han enviado vínculos a prevalidación.</div><?php endif; ?>
<?php foreach($vinculos as $v): ?><article class="cruce-approval"><div class="cruce-heading"><h6><?=ce($v['CODIGO'])?> ↔ Movimiento #<?=(int)$v['MOVIMIENTO_ID']?></h6><span class="cruce-pill"><?=ce($v['ESTADO'])?></span></div><div class="cruce-table-wrap"><table class="table"><thead><tr><th>Dato</th><th>Depósito</th><th>Movimiento bancario</th></tr></thead><tbody><tr><th>Referencia</th><td><?=ce($v['NUMERO_REFERENCIA'])?></td><td><?=ce($v['REFERENCIA'])?></td></tr><tr><th>Monto / crédito</th><td><?=ce($v['MONTO'])?></td><td><?=ce($v['CREDITO'])?></td></tr><tr><th>Fecha y hora</th><td><?=ce($v['FECHA_DEPOSITO']?:'No informada')?></td><td><?=ce($v['FECHA'])?> <?=ce($v['HORA']?:'Hora no informada')?></td></tr></tbody></table></div><p>Cuenta <?=ce($v['NUMERO_CUENTA'])?> · <?=ce($v['MONEDA'])?></p><?php $comprobante=conciliacionFoto($v['FOTO_URL']??null); if($comprobante): ?><p><a class="btn btn-outline-primary btn-sm" href="<?=ce($comprobante)?>" target="_blank" rel="noopener">Ver comprobante</a></p><?php endif; ?><p>Enviado por<?=ce($v['REVISOR'])?> · <?=ce($v['CREADO_EN'])?></p><p><strong>Observación:</strong> <?=ce($v['OBSERVACION'])?></p><?php if($v['MOTIVO']): ?><p><strong>Decisión:</strong> <?=ce($v['MOTIVO'])?></p><?php endif; ?>
<?php if($v['ESTADO']==='PREVALIDADO'): if(!$cerrado && $supervisor && (int)$v['CREADO_POR']!==(int)$_SESSION['user_id']): ?><form method="post"><?php camposCruce($eid); ?><input type="hidden" name="vinculo" value="<?=(int)$v['ID']?>"><label>Comentario / motivo de devolución<input class="form-control" name="observacion" maxlength="1000"></label><div class="cruce-actions"><button class="btn btn-success" name="accion" value="aprobar">Aprobar vínculo</button><button class="btn btn-outline-danger" name="accion" value="devolver">Devolver para corregir</button></div></form><?php else: ?><div class="alert alert-info"><?php if(empty($periodoHabilitado)): ?>Este mes está bloqueado. No se puede aprobar ni devolver este vínculo hasta habilitar su período.<?php elseif(!$supervisor): ?>Tu rol de Analista Contable permite preparar cruces, pero no aprobarlos. Un usuario con rol Supervisor o Administrador debe revisar este vínculo.<?php else: ?>Este vínculo fue enviado con tu usuario. Otro Supervisor o Administrador debe aprobarlo.<?php endif; ?></div><?php endif; endif; ?><?php if($supervisor && !$cerrado && in_array($v['ESTADO'],['PREVALIDADO','APROBADO'],true)): ?><details><summary>El depósito aprobado tiene datos incorrectos</summary><form method="post"><?php camposCruce($eid); ?><input type="hidden" name="accion" value="solicitar_correccion"><input type="hidden" name="deposito" value="<?=(int)$v['DEPOSITO_ID']?>"><label>Motivo de corrección<textarea class="form-control" name="observacion" required maxlength="500" rows="2"></textarea></label><p>Se devolverá el depósito al analista y se liberará este vínculo, conservando el historial.</p><button class="btn btn-outline-primary">Devolver depósito para corrección</button></form></details><?php endif; ?></article><?php endforeach; ?></div></section>
